"""Build departure boards from a timetable feed (see /app/docs)."""
import csv
import io
import json
import os
import sys
from collections import defaultdict
from datetime import date, datetime, timedelta, timezone
from zoneinfo import ZoneInfo


def read_csv(directory, name):
    path = os.path.join(directory, name)
    if not os.path.exists(path):
        return []
    with open(path, "r", encoding="utf-8-sig", newline="") as f:
        text = f.read()
    if text.startswith("\ufeff"):
        text = text[1:]
    reader = csv.reader(io.StringIO(text, newline=""))
    header = None
    rows = []
    for rec in reader:
        if not rec or all(c.strip() == "" for c in rec):
            continue
        if header is None:
            header = [c.strip().lstrip("\ufeff") for c in rec]
            continue
        row = {}
        for i, h in enumerate(header):
            v = rec[i].strip() if i < len(rec) else ""
            if h not in row or v != "":
                row[h] = v
        rows.append(row)
    return rows


def parse_time(s):
    h, m, sec = s.split(":")
    return int(h) * 3600 + int(m) * 60 + int(sec)


def parse_date(s):
    return date(int(s[0:4]), int(s[4:6]), int(s[6:8]))


_tzcache = {}


def tz(name):
    if name not in _tzcache:
        _tzcache[name] = ZoneInfo(name)
    return _tzcache[name]


def origin(d, tzname):
    """Noon of date d in zone, minus 12 hours elapsed, as an aware UTC datetime."""
    z = tz(tzname)
    noon = datetime(d.year, d.month, d.day, 12, 0, 0, tzinfo=z)
    noon_utc = noon.astimezone(timezone.utc)
    return noon_utc - timedelta(hours=12)


def fmt(instant_utc, tzname):
    local = instant_utc.astimezone(tz(tzname))
    off = local.utcoffset()
    secs = int(off.total_seconds())
    sign = "+" if secs >= 0 else "-"
    secs = abs(secs)
    return "%04d-%02d-%02dT%02d:%02d:%02d%s%02d:%02d" % (
        local.year, local.month, local.day, local.hour, local.minute,
        local.second, sign, secs // 3600, (secs % 3600) // 60)


def to_int(s, default=None):
    if s is None or s == "":
        return default
    return int(s)


def main():
    indir, outfile = sys.argv[1], sys.argv[2]

    with open(os.path.join(indir, "request.json"), "r", encoding="utf-8-sig") as f:
        request = json.load(f)
    dates = sorted(set(request["service_dates"]))
    date_objs = {d: date.fromisoformat(d) for d in dates}

    agencies = read_csv(indir, "agency.txt")
    stops = {r["stop_id"]: r for r in read_csv(indir, "stops.txt")}
    routes = {r["route_id"]: r for r in read_csv(indir, "routes.txt")}
    trips = {r["trip_id"]: r for r in read_csv(indir, "trips.txt")}
    calendar = {r["service_id"]: r for r in read_csv(indir, "calendar.txt")}
    cal_dates = {}
    for r in read_csv(indir, "calendar_dates.txt"):
        cal_dates[(r["service_id"], r["date"])] = to_int(r.get("exception_type"))
    agency_tz = {}
    for a in agencies:
        agency_tz[a.get("agency_id", "")] = a["agency_timezone"]
    default_tz = agencies[0]["agency_timezone"] if agencies else "UTC"

    stop_times = defaultdict(list)
    for r in read_csv(indir, "stop_times.txt"):
        stop_times[r["trip_id"]].append(r)

    freqs = defaultdict(list)
    for r in read_csv(indir, "frequencies.txt"):
        freqs[r["trip_id"]].append(r)

    weekdays = ["monday", "tuesday", "wednesday", "thursday", "friday",
                "saturday", "sunday"]

    def runs(service_id, d):
        key = (service_id, d.strftime("%Y%m%d"))
        ex = cal_dates.get(key)
        if ex == 1:
            return True
        if ex == 2:
            return False
        c = calendar.get(service_id)
        if not c:
            return False
        if not (parse_date(c["start_date"]) <= d <= parse_date(c["end_date"])):
            return False
        return c.get(weekdays[d.weekday()], "") == "1"

    def stop_name_of_board(stop_id):
        s = stops[stop_id]
        p = s.get("parent_station", "")
        if p and p in stops:
            return stops[p].get("stop_name", "")
        return s.get("stop_name", "")

    def board_id(stop_id):
        s = stops[stop_id]
        p = s.get("parent_station", "")
        if p:
            return p
        return stop_id

    # board stops
    board_stops = []
    for sid, s in stops.items():
        lt = s.get("location_type", "")
        if lt == "1":
            board_stops.append(sid)
        elif lt in ("", "0") and not s.get("parent_station", ""):
            board_stops.append(sid)

    def board_tz(sid):
        return stops[sid].get("stop_timezone", "") or default_tz

    # Precompute per-trip stop patterns
    trip_info = {}
    for tid, trip in trips.items():
        rows = stop_times.get(tid, [])
        if not rows:
            continue
        rows = sorted(rows, key=lambda r: int(r["stop_sequence"]))
        n = len(rows)
        times = []
        for r in rows:
            t = r.get("departure_time", "") or r.get("arrival_time", "")
            times.append(parse_time(t) if t else None)
        known = [i for i, t in enumerate(times) if t is not None]
        for i in range(n):
            if times[i] is None:
                b = max(k for k in known if k < i)
                a = min(k for k in known if k > i)
                times[i] = times[b] + ((times[a] - times[b]) * (i - b)) // (a - b)
        last_stop = rows[-1]["stop_id"]
        trip_headsign = trip.get("trip_headsign", "")
        route = routes[trip["route_id"]]
        label = route.get("route_short_name", "") or route.get("route_long_name", "")
        last_name = stop_name_of_board(last_stop)
        deps = []  # (time, stop_id, headsign, platform)
        for i, r in enumerate(rows):
            if i == n - 1:
                continue
            if r.get("pickup_type", "") == "1":
                continue
            hs = r.get("stop_headsign", "") or trip_headsign or last_name
            sid = r["stop_id"]
            plat = stops[sid].get("platform_code", "") or None
            deps.append((times[i], sid, hs, plat))
        trip_info[tid] = (label, route.get("agency_id", ""), deps, times[0])

    boards = {}
    for sid in board_stops:
        for d in dates:
            boards[(sid, d)] = []

    for d in dates:
        dobj = date_objs[d]
        for tid, trip in trips.items():
            if tid not in trip_info:
                continue
            if not runs(trip["service_id"], dobj):
                continue
            label, agency_id, deps, first_time = trip_info[tid]
            atz = agency_tz.get(agency_id, default_tz)
            org = origin(dobj, atz)

            def inst(secs):
                return org + timedelta(seconds=secs)

            entries = []  # (instant, until, headway, kind, sid, hs, plat)
            if tid in freqs:
                for w in freqs[tid]:
                    start = parse_time(w["start_time"])
                    end = parse_time(w["end_time"])
                    h = int(w["headway_secs"])
                    if start >= end:
                        continue
                    count = (end - 1 - start) // h + 1
                    exact = to_int(w.get("exact_times"), 0) == 1
                    for (t, sid, hs, plat) in deps:
                        off = t - first_time
                        if exact:
                            for k in range(count):
                                entries.append((inst(start + k * h + off), None, None,
                                                "scheduled", sid, hs, plat))
                        else:
                            entries.append((inst(start + off),
                                            inst(start + (count - 1) * h + off), h,
                                            "interval", sid, hs, plat))
            else:
                for (t, sid, hs, plat) in deps:
                    entries.append((inst(t), None, None, "scheduled", sid, hs, plat))

            for (when, until, h, kind, sid, hs, plat) in entries:
                bid = board_id(sid)
                key = (bid, d)
                if key not in boards:
                    continue
                btz = board_tz(bid)
                boards[key].append((when, label, hs, tid, plat, {
                    "kind": kind,
                    "time": fmt(when, btz),
                    "until": fmt(until, btz) if until is not None else None,
                    "headway_secs": h,
                    "route": label,
                    "headsign": hs,
                    "trip": tid,
                    "platform": plat,
                    "agency": agency_id,
                }))

    out_boards = []
    for (sid, d) in sorted(boards.keys()):
        items = boards[(sid, d)]
        items.sort(key=lambda x: (x[0], x[1], x[2], x[3],
                                  (0, "") if x[4] is None else (1, x[4])))
        out_boards.append({
            "stop_id": sid,
            "name": stops[sid].get("stop_name", ""),
            "timezone": board_tz(sid),
            "service_date": d,
            "departures": [x[5] for x in items],
        })

    with open(outfile, "w", encoding="utf-8") as f:
        json.dump({"service_dates": dates, "boards": out_boards}, f,
                  ensure_ascii=False, indent=1)


if __name__ == "__main__":
    main()
